```javascript
function frequenceMots(phrase) {
  if (!phrase) return {};
  const mots = phrase.split(/\s+/);
  const frequences = {};

  for (let mot of mots) {
    if (mot === "") continue;
    frequences[mot] = (frequences[mot] || 0) + 1;
  }

  return frequences;
}
```

