/**
 * Sorts an array of numbers in ascending order without using Array.prototype.sort().
 * Implementation: QuickSort algorithm.
 * @param {number[]} arr - The array to sort.
 * @returns {number[]} - The sorted array.
 */
function trier_tableau(arr) {
    if (arr.length <= 1) return arr;

    const quickSort = (array, left, right) => {
        if (left < right) {
            let pivotIndex = partition(array, left, right);
            quickSort(array, left, pivotIndex - 1);
            quickSort(array, pivotIndex + 1, right);
        }
    };

    const partition = (array, left, right) => {
        const pivot = array[right];
        let i = left - 1;
        for (let j = left; j < right; j++) {
            if (array[j] <= pivot) {
                i++;
                [array[i], array[j]] = [array[j], array[i]];
            }
        }
        [array[i + 1], array[right]] = [array[right], array[i + 1]];
        return i + 1;
    };

    // Work on a copy to avoid mutating the original input if desired, 
    // but standard sort behavior usually allows mutation or returns new.
    // Here we return a sorted version.
    const result = [...arr];
    quickSort(result, 0, result.length - 1);
    return result;
}
